function optimizeConfigUpdates(initialConfig, updates, subscribedComponents) {
  const getByPath = (obj, path) => {
    return path.split('.').reduce((acc, part) => (acc && acc[part] !== undefined) ? acc[part] : undefined, obj);
  };

  const deepEqual = (a, b) => {
    if (a === b) return true;
    if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) return false;

    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    if (keysA.length !== keysB.length) return false;

    for (const key of keysA) {
      if (!keysB.includes(key) || !deepEqual(a[key], b[key])) {
        return false;
      }
    }
    return true;
  };

  let currentConfig = JSON.parse(JSON.stringify(initialConfig));
  const renderCounts = Object.fromEntries(Object.keys(subscribedComponents).map(name => [name, 0]));

  for (const update of updates) {
    const prevConfig = JSON.parse(JSON.stringify(currentConfig));

    const pathParts = update.path.split('.');
    let target = currentConfig;
    for (let i = 0; i < pathParts.length - 1; i++) {
      if (!target[pathParts[i]] || typeof target[pathParts[i]] !== 'object') {
        target[pathParts[i]] = {};
      }
      target = target[pathParts[i]];
    }
    target[pathParts[pathParts.length - 1]] = update.value;

    for (const componentName in subscribedComponents) {
      const pathsToObserve = subscribedComponents[componentName];
      let shouldRender = false;
      for (const path of pathsToObserve) {
        const prevValue = getByPath(prevConfig, path);
        const currentValue = getByPath(currentConfig, path);
        if (!deepEqual(prevValue, currentValue)) {
          shouldRender = true;
          break;
        }
      }
      if (shouldRender) {
        renderCounts[componentName]++;
      }
    }
  }

  return renderCounts;
}

