import json

def get_by_path(obj, path):
    parts = path.split('.')
    for part in parts:
        if isinstance(obj, dict) and part in obj:
            obj = obj[part]
        else:
            return None
    return obj

def deep_equal(a, b):
    if a == b: 
        return True
    if not isinstance(a, dict) or not isinstance(b, dict) or a is None or b is None:
        return False

    if len(a) != len(b):
        return False

    for key in a:
        if key not in b or not deep_equal(a[key], b[key]):
            return False
    return True

def optimizeConfigUpdates(initial_config, updates, subscribed_components):
    current_config = json.loads(json.dumps(initial_config))
    render_counts = {name: 0 for name in subscribed_components}

    for update in updates:
        prev_config = json.loads(json.dumps(current_config))

        path_parts = update['path'].split('.')
        target = current_config
        for i in range(len(path_parts) - 1):
            if path_parts[i] not in target or not isinstance(target[path_parts[i]], dict):
                target[path_parts[i]] = {}
            target = target[path_parts[i]]
        target[path_parts[-1]] = update['value']

        for component_name, paths_to_observe in subscribed_components.items():
            should_render = False
            for path in paths_to_observe:
                prev_value = get_by_path(prev_config, path)
                current_value = get_by_path(current_config, path)
                if not deep_equal(prev_value, current_value):
                    should_render = True
                    break
            if should_render:
                render_counts[component_name] += 1

    return render_counts

