function calculateOptimizedCartState(initialState, actions) {
  let currentState = JSON.parse(JSON.stringify(initialState));
  let totalPriceRecomputations = 0;
  let itemCountRecomputations = 0;

  let memoizedTotalPrice = null;
  let memoizedItemCount = null;

  const calculateTotalPrice = (items, discounts) => {
    let total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    for (const discount of discounts) {
      total -= total * discount.amount;
    }
    return total;
  };

  const calculateItemCount = (items) => {
    return items.reduce((sum, item) => sum + item.quantity, 0);
  };

  memoizedTotalPrice = calculateTotalPrice(currentState.items, currentState.discounts);
  memoizedItemCount = calculateItemCount(currentState.items);

  for (const action of actions) {
    const previousItems = currentState.items;
    const previousDiscounts = currentState.discounts;

    if (action.type === 'ADD_ITEM') {
      const existingItemIndex = currentState.items.findIndex(item => item.id === action.payload.id);
      if (existingItemIndex !== -1) {
        currentState.items = currentState.items.map((item, index) => 
          index === existingItemIndex ? { ...item, quantity: item.quantity + action.payload.quantity } : item
        );
      } else {
        currentState.items = [...currentState.items, action.payload];
      }
    } else if (action.type === 'REMOVE_ITEM') {
      currentState.items = currentState.items.filter(item => item.id !== action.payload.id);
    } else if (action.type === 'UPDATE_QUANTITY') {
      currentState.items = currentState.items.map(item => 
        item.id === action.payload.id ? { ...item, quantity: action.payload.quantity } : item
      );
    } else if (action.type === 'APPLY_DISCOUNT') {
      currentState.discounts = [...currentState.discounts, action.payload];
    }

    const itemsChanged = previousItems !== currentState.items;
    const discountsChanged = previousDiscounts !== currentState.discounts;

    if (itemsChanged || discountsChanged) {
      if (itemsChanged || discountsChanged) {
        memoizedTotalPrice = calculateTotalPrice(currentState.items, currentState.discounts);
        totalPriceRecomputations++;
      }
      if (itemsChanged) {
        memoizedItemCount = calculateItemCount(currentState.items);
        itemCountRecomputations++;
      }
    }
  }

  return {
    finalState: currentState,
    selectorRecomputations: {
      getTotalPrice: totalPriceRecomputations,
      getItemCount: itemCountRecomputations,
    },
  };
}

