import json

def calculateOptimizedCartState(initial_state, actions):
    current_state = json.loads(json.dumps(initial_state))
    total_price_recomputations = 0
    item_count_recomputations = 0

    memoized_total_price = None
    memoized_item_count = None

    def calculate_total_price(items, discounts):
        total = sum(item['price'] * item['quantity'] for item in items)
        for discount in discounts:
            total -= total * discount['amount']
        return total

    def calculate_item_count(items):
        return sum(item['quantity'] for item in items)

    memoized_total_price = calculate_total_price(current_state['items'], current_state['discounts'])
    memoized_item_count = calculate_item_count(current_state['items'])

    for action in actions:
        previous_items_ref = current_state['items']
        previous_discounts_ref = current_state['discounts']

        if action['type'] == 'ADD_ITEM':
            existing_item_index = -1
            for i, item in enumerate(current_state['items']):
                if item['id'] == action['payload']['id']:
                    existing_item_index = i
                    break

            if existing_item_index != -1:
                new_items = list(current_state['items'])
                new_items[existing_item_index] = {**new_items[existing_item_index], 'quantity': new_items[existing_item_index]['quantity'] + action['payload']['quantity']}
                current_state['items'] = new_items
            else:
                current_state['items'] = current_state['items'] + [action['payload']]
        elif action['type'] == 'REMOVE_ITEM':
            current_state['items'] = [item for item in current_state['items'] if item['id'] != action['payload']['id']]
        elif action['type'] == 'UPDATE_QUANTITY':
            current_state['items'] = [
                {**item, 'quantity': action['payload']['quantity']} if item['id'] == action['payload']['id'] else item
                for item in current_state['items']
            ]
        elif action['type'] == 'APPLY_DISCOUNT':
            current_state['discounts'] = current_state['discounts'] + [action['payload']]

        items_changed = previous_items_ref is not current_state['items']
        discounts_changed = previous_discounts_ref is not current_state['discounts']

        if items_changed or discounts_changed:
            if items_changed or discounts_changed:
                memoized_total_price = calculate_total_price(current_state['items'], current_state['discounts'])
                total_price_recomputations += 1
            if items_changed:
                memoized_item_count = calculate_item_count(current_state['items'])
                item_count_recomputations += 1

    return {
        'finalState': current_state,
        'selectorRecomputations': {
            'getTotalPrice': total_price_recomputations,
            'getItemCount': item_count_recomputations,
        },
    }

