function simulateDebouncedSearch(inputSequence, debounceDelay) {
  if (inputSequence.length === 0) return [];

  const triggeredQueries = [];
  let lastStableInput = null;

  for (const input of inputSequence) {
    if (lastStableInput === null) {
      lastStableInput = input;
    } else {
      if (input.timestamp < lastStableInput.timestamp + debounceDelay) {
        lastStableInput = input;
      } else {
        triggeredQueries.push({
          query: lastStableInput.value,
          triggeredAt: lastStableInput.timestamp + debounceDelay,
        });
        lastStableInput = input;
      }
    }
  }

  if (lastStableInput !== null) {
    triggeredQueries.push({
      query: lastStableInput.value,
      triggeredAt: lastStableInput.timestamp + debounceDelay,
    });
  }

  return triggeredQueries.sort((a, b) => a.triggeredAt - b.triggeredAt);
}

