def simulateDebouncedSearch(input_sequence, debounce_delay):
    if not input_sequence: 
        return []

    triggered_queries = []
    last_stable_input = None

    for input_item in input_sequence:
        if last_stable_input is None:
            last_stable_input = input_item
        else:
            if input_item['timestamp'] < last_stable_input['timestamp'] + debounce_delay:
                last_stable_input = input_item
            else:
                triggered_queries.append({
                    'query': last_stable_input['value'],
                    'triggeredAt': last_stable_input['timestamp'] + debounce_delay,
                })
                last_stable_input = input_item

    if last_stable_input is not None:
        triggered_queries.append({
            'query': last_stable_input['value'],
            'triggeredAt': last_stable_input['timestamp'] + debounce_delay,
        })

    return sorted(triggered_queries, key=lambda x: x['triggeredAt'])

