function resolveErrorPropagation(componentTree, errorOrigin) {
  let pathFromRoot = [];

  function findPath(node, targetName, currentPath) {
    if (!node) return null;
    currentPath.push(node);
    if (node.name === targetName) {
      return currentPath.slice();
    }
    if (node.children) {
      for (const child of node.children) {
        const result = findPath(child, targetName, currentPath);
        if (result) return result;
      }
    }
    currentPath.pop();
    return null;
  }

  pathFromRoot = findPath(componentTree, errorOrigin, []);

  if (!pathFromRoot) {
    return "Error origin not found";
  }

  for (let i = pathFromRoot.length - 1; i >= 0; i--) {
    const component = pathFromRoot[i];
    if (component.name === errorOrigin) continue;
    if (component.hasErrorBoundary) {
      return `Error caught by ${component.name}`;
    }
  }

  return "Uncaught Error";
}

