def resolveErrorPropagation(component_tree, error_origin):
    path_from_root = []

    def find_path(node, target_name, current_path):
        if not node: 
            return None
        current_path.append(node)
        if node['name'] == target_name:
            return list(current_path)

        if 'children' in node and node['children']:
            for child in node['children']:
                result = find_path(child, target_name, current_path)
                if result: 
                    return result
        current_path.pop()
        return None

    path_from_root = find_path(component_tree, error_origin, [])

    if not path_from_root:
        return "Error origin not found"

    for i in range(len(path_from_root) - 1, -1, -1):
        component = path_from_root[i]
        if component['name'] == error_origin:
            continue
        if component.get('hasErrorBoundary', False):
            return f"Error caught by {component['name']}"

    return "Uncaught Error"

