function simulateModuleLoading(modules, entryModule, successfulModules) {
  const successfullyLoaded = new Set(successfulModules);
  const loadedOrder = [];
  const visited = new Set();
  const loadingStack = new Set(); 

  function dfsLoad(moduleName) {
    if (loadingStack.has(moduleName)) {
      return false; 
    }
    if (visited.has(moduleName)) {
      return true;
    }

    if (!successfullyLoaded.has(moduleName)) {
      return false;
    }

    loadingStack.add(moduleName);

    const module = modules[moduleName];
    if (module && module.dependencies) {
      for (const dep of module.dependencies) {
        if (!dfsLoad(dep)) {
          loadingStack.delete(moduleName);
          return false;
        }
      }
    }

    loadingStack.delete(moduleName);
    visited.add(moduleName);
    loadedOrder.push(module.content);
    return true;
  }

  if (!dfsLoad(entryModule)) {
    visited.clear(); 
    loadingStack.clear();

    function findFailingModule(moduleName) {
        if (loadingStack.has(moduleName)) return moduleName;
        if (!successfullyLoaded.has(moduleName)) return moduleName;
        if (visited.has(moduleName)) return null;

        loadingStack.add(moduleName);
        const module = modules[moduleName];
        if (module && module.dependencies) {
            for (const dep of module.dependencies) {
                const failedDep = findFailingModule(dep);
                if (failedDep) {
                    loadingStack.delete(moduleName);
                    return failedDep;
                }
            }
        }
        loadingStack.delete(moduleName);
        visited.add(moduleName);
        return null;
    }

    const failingModule = findFailingModule(entryModule);
    if(failingModule) {
        return `Failed to load: ${failingModule}`;
    } else {
        return `Failed to load a dependency for ${entryModule}`;
    }
  }

  return loadedOrder;
}

