def simulateModuleLoading(modules, entry_module, successful_modules):
    successfully_loaded = set(successful_modules)
    loaded_order = []
    visited = set()
    loading_stack = set() 

    def dfs_load(module_name):
        if module_name in loading_stack:
            return False
        if module_name in visited:
            return True

        if module_name not in successfully_loaded:
            return False

        loading_stack.add(module_name)

        module = modules.get(module_name)
        if module and 'dependencies' in module:
            for dep in module['dependencies']:
                if not dfs_load(dep):
                    loading_stack.remove(module_name)
                    return False

        loading_stack.remove(module_name)
        visited.add(module_name)
        loaded_order.append(module['content'])
        return True

    if not dfs_load(entry_module):
        visited.clear()
        loading_stack.clear()

        def find_failing_module(module_name_inner):
            if module_name_inner in loading_stack: return module_name_inner
            if module_name_inner not in successfully_loaded: return module_name_inner
            if module_name_inner in visited: return None

            loading_stack.add(module_name_inner)
            module_inner = modules.get(module_name_inner)
            if module_inner and 'dependencies' in module_inner:
                for dep_inner in module_inner['dependencies']:
                    failed_dep = find_failing_module(dep_inner)
                    if failed_dep:
                        loading_stack.remove(module_name_inner)
                        return failed_dep
            loading_stack.remove(module_name_inner)
            visited.add(module_name_inner)
            return None

        failing_module = find_failing_module(entry_module)
        if failing_module:
            return f"Failed to load: {failing_module}"
        else:
            return f"Failed to load a dependency for {entry_module}"

    return loaded_order
